def safe_mean(nums: list[float]) -> float:
    if not nums:
        return 0.0
    total = 0
    for value in nums:
        total += value
    return total / len(nums)

def clamp(value: float, low: float, high: float) -> float:
    if low > high:
        raise ValueError("low must not exceed high")
    return min(high, max(low, value))
